# Preserve the route's MOVE order when weed recovery inserts DIG.  The old
# fixed replay always discarded source step +9; if that source is a MOVE, use
# the first PASS within this day/16-turn window instead.  No PASS means the
# byte-for-byte legacy transaction remains the fallback.
def _stable_early_weed_gate(step, actor, position, intended):
    return step == 33 and actor == 1


def _install_minloss_pass_weed(namespace, hire_mode="none", minimum_step=240,
                               early_gate=None):
    moves = {"NORTH", "SOUTH", "EAST", "WEST"}
    audit = namespace.setdefault("_MINLOSS_PASS_AUDIT", {0: [], 1: []})

    def actions(obs):
        route = namespace.get("_kawa_actions")
        return list(route(obs) if callable(route) else namespace.get("_ACTIONS") or [])

    def source(obs, step, actor):
        tape = actions(obs)
        if step < 0 or step >= len(tape):
            return ["PASS"]
        frame = tape[step] or {}
        if actor == "farmer":
            return list(frame.get("farmer") or ["PASS"])
        hands = list(frame.get("hands") or [])
        return list(hands[int(actor)] if int(actor) < len(hands) else ["PASS"])

    def blocked(obs, step, actor):
        if hire_mode == "k320":
            guard = namespace.get("_mass_hire_farmer_barrier")
            return actor == "farmer" and callable(guard) and bool(guard(obs, step))
        if hire_mode != "split":
            return False
        horizon = 4 if actor == "farmer" else 2
        hires = 0
        tape = actions(obs)
        for offset in range(horizon + 1):
            index = step + offset
            if index >= len(tape):
                break
            for order in list((tape[index] or {}).get("market") or []):
                hires += bool(isinstance(order, (list, tuple)) and order and order[0] == "HIRE")
        return hires >= (5 if actor == "farmer" else 1)

    def repair(obs, action, step):
        action = namespace["_align_hands"](action, obs)
        seat = namespace["_seat"](obs)
        game = namespace["_WEED_STATE"][seat]
        if step == 0 or step < game.get("last_step", -1):
            game = {"last_step": step, "active": {}}
            namespace["_WEED_STATE"][seat] = game
            audit[seat] = []
        game["last_step"] = step
        farm = namespace["_farm"](obs, seat)
        positions = [
            namespace["_get"](farm, "farmer"),
            *list(namespace["_get"](farm, "hands", []) or []),
        ]
        unit_actions = [action.get("farmer", ["PASS"]), *list(action.get("hands") or [])]
        active = game["active"]

        for actor, transaction in list(active.items()):
            index = 0 if actor == "farmer" else int(actor) + 1
            if index >= len(unit_actions):
                active.pop(actor, None)
                continue
            skip_step = transaction.get("skip_step")
            if skip_step is not None:
                if step <= skip_step:
                    unit_actions[index] = source(obs, step - 1, actor)
                else:
                    active.pop(actor, None)
                continue
            if blocked(obs, step, actor):
                active.pop(actor, None)
                continue
            age = step - transaction["start"]
            if age == 1:
                unit_actions[index] = list(transaction["intended"])
            elif 2 <= age <= 9:
                unit_actions[index] = source(obs, step - 1, actor)
            else:
                active.pop(actor, None)

        tape = actions(obs)
        for index, (position, intended) in enumerate(zip(positions, unit_actions)):
            actor = "farmer" if index == 0 else index - 1
            if actor in active or blocked(obs, step, actor):
                continue
            if not isinstance(intended, list) or not intended or intended[0] not in ("BUILD_PASTURE", "PLANT"):
                continue
            tile = namespace["_tile_at"](farm, position)
            if not isinstance(tile, dict) or tile.get("kind") != "WEED":
                continue
            legacy = source(obs, step + 9, actor)
            skip = None
            for candidate in range(step, min(len(tape) - 1, (step // 24 + 1) * 24 - 1, step + 16) + 1):
                candidate_op = source(obs, candidate, actor)[0]
                if candidate_op in moves:
                    break
                if candidate_op == "PASS":
                    skip = candidate
                    break
            transaction = {"start": step, "intended": list(intended)}
            early = callable(early_gate) and early_gate(step, actor, position, intended)
            if (step >= minimum_step or early) and legacy and legacy[0] in moves and skip is not None:
                transaction["skip_step"] = skip
                audit[seat].append({
                    "step": step, "actor": actor, "skip_step": skip,
                    "position": list(position), "intended": list(intended),
                    "legacy_move": legacy[0], "hire_mode": hire_mode,
                })
            active[actor] = transaction
            unit_actions[index] = ["DIG"]

        action["farmer"] = unit_actions[0] if unit_actions else ["PASS"]
        action["hands"] = unit_actions[1:]
        return namespace["_align_hands"](action, obs)

    namespace["_weed_repair_action"] = repair


_FC24B_BASE = _BASE.__dict__
_install_minloss_pass_weed(_FC24B_BASE["_K320"].__dict__, "k320", early_gate=_stable_early_weed_gate)
_install_minloss_pass_weed(_FC24B_BASE["_LEGACY"].__dict__, early_gate=_stable_early_weed_gate)
_install_minloss_pass_weed(_FC24B_BASE["_PRT"].__dict__, "split", early_gate=_stable_early_weed_gate)
_install_minloss_pass_weed(_FC24B_BASE["_X562"].__dict__["_X540_NS"], "split", early_gate=_stable_early_weed_gate)


# Route-only intervention seam.
#
# The frozen teammate submission remains the action owner.  A policy installed
# through ``set_meta_route_policy`` may only choose between already embedded
# route branches; production execution, legality repair, market ordering,
# opponent-market adaptation and terminal handling remain untouched.
_META_ROUTE_POLICY = None
_META_K320_ROUTES = (
    "10c4s_3q",
    "8c6s_3q",
    "6c8s_3q",
    "6c12s_4q_first_yarn",
    "6c12s_4q_second_yarn",
)


def set_meta_route_policy(policy):
    """Install a route selector, or restore teammate defaults with ``None``.

    The callable receives keyword arguments ``decision``, ``obs``, ``default``,
    ``choices`` and ``state``.  Invalid results and policy errors fall back to
    the original teammate decision so evaluation cannot corrupt action logic.
    """
    global _META_ROUTE_POLICY
    _META_ROUTE_POLICY = policy


def _meta_route_choice(decision, obs, default, choices, state):
    policy = _META_ROUTE_POLICY
    if policy is None:
        return default
    try:
        selected = policy(
            decision=decision,
            obs=obs,
            default=default,
            choices=tuple(choices),
            state=dict(state or {}),
        )
    except Exception:
        return default
    return selected if selected in choices else default


# K320 owns five compatible shop-routed tapes.  Replacing only its upstream
# label leaves K320's existing route lock, farm rebind and all action overlays
# in force.
_META_K320 = _BASE.__dict__["_K320"]
_META_ORIGINAL_K320_SHOP_ROUTE = _META_K320.__dict__["_K320_SHOP_ROUTE"]


def _meta_k320_shop_route(obs):
    default = _META_ORIGINAL_K320_SHOP_ROUTE(obs)
    seat = _BASE.__dict__["_seat"](obs)
    state = _BASE.__dict__["_STATE"][seat]
    return _meta_route_choice(
        "k320_route", obs, default, _META_K320_ROUTES, state
    )


_META_K320.__dict__["_K320_SHOP_ROUTE"] = _meta_k320_shop_route


def _meta_base_agent(obs, configuration=None):
    """Byte-for-byte teammate control flow with only route predicates exposed."""
    base = _BASE.__dict__
    obs = _step_normalized(obs)
    step = min(max(0, _step_of(obs)), 718)
    seat = base["_seat"](obs)
    state = base["_reset_if_needed"](seat, step)

    k320_action = base["_call"](base["_K320"], obs, configuration)

    default_pressure = base["_visible_opening_sheep_pressure"](obs, seat, step)
    pressure = _meta_route_choice(
        "opening_pressure", obs, bool(default_pressure), (False, True), state
    )
    if pressure:
        state["sheep_pressure"] = True

    if not state["sheep_pressure"] and step >= 96:
        return k320_action

    # Preserve the original shadow execution so a later handoff enters a fully
    # synchronized stateful policy rather than a cold replay suffix.
    prt_action = base["_call"](base["_PRT"], obs, configuration)
    if state["route"] is None:
        x562_action = base["_call"](base["_X562"], obs, configuration)
        legacy_action = base["_call"](base["_LEGACY"], obs, configuration)
    else:
        x562_action = legacy_action = None

    if not state["sheep_pressure"]:
        return k320_action

    if state["route"] is None and step >= 168:
        default_owner = "x562"
        state["route"] = _meta_route_choice(
            "pressure_route",
            obs,
            default_owner,
            ("x562", "legacy"),
            state,
        )

    if state.get("route") == "legacy":
        branch_action = (
            legacy_action
            if legacy_action is not None
            else base["_call"](base["_LEGACY"], obs, configuration)
        )
    else:
        branch_action = (
            x562_action
            if x562_action is not None
            else base["_call"](base["_X562"], obs, configuration)
        )

    if step == 288 and not state["prt"]:
        shops = base["_shops"](obs)
        own_money = int(base["_get"](base["_farm"](obs, seat), "money", 0) or 0)
        default_prt = (
            own_money <= 13376
            and sum(value == "YARN_STORE" for value in shops) <= 1
            and base["_market_inventory"](obs, "STRAWBERRY") <= 9979
        )
        state["prt"] = _meta_route_choice(
            "late_prt", obs, bool(default_prt), (False, True), state
        )
    if state["prt"]:
        return prt_action
    return branch_action


_BASE.__dict__["agent"] = _meta_base_agent


_PRODUCTS = (
    "WHEAT", "CARROT", "TOMATO", "STRAWBERRY", "MELON",
    "EGG", "MILK", "WOOL", "FERTILIZER",
)
_CROP_FIRST_YIELD_DAY = {
    "WHEAT": 2,
    "CARROT": 2,
    "TOMATO": 8,
    "STRAWBERRY": 10,
    "MELON": 10,
}
# Exact CPython/JAX order frozen by high_potential_v20_gpu._EVAC_ACCESS.
_EVAC_ACCESS = ((4, 4), (5, 4), (5, 5), (4, 5))
_MOVE_OPS = {"NORTH", "SOUTH", "EAST", "WEST"}
_ANIMAL_PRODUCT = {"GOOSE": "EGG", "COW": "MILK", "SHEEP": "WOOL"}
_STATE = {
    0: {
        "last_step": -1,
        "wheat_credit": 0,
        "salvage_active": False,
        "salvage_actor": -1,
        "salvage_target": (0, 0),
        "salvage_product": None,
        "salvage_quantity": 0,
    },
    1: {
        "last_step": -1,
        "wheat_credit": 0,
        "salvage_active": False,
        "salvage_actor": -1,
        "salvage_target": (0, 0),
        "salvage_product": None,
        "salvage_quantity": 0,
    },
}


def _get(value, key, default=None):
    if isinstance(value, dict):
        return value.get(key, default)
    return getattr(value, key, default)


def _step_of(obs):
    """Game step from the public clock.

    The official interpreter sets ``step`` on player 0's observation only;
    player 1 receives ``day`` and ``hour`` alone.  Every step-indexed state
    machine below (tape playback, transaction tracking, route schedule) would
    otherwise read step zero for a whole game, so derive it from the clock.
    """
    day = _get(obs, "day", None)
    hour = _get(obs, "hour", None)
    if day is not None and hour is not None:
        return int(day) * 24 + int(hour)
    return int(_get(obs, "step", 0) or 0)


def _step_normalized(obs):
    """Return ``obs`` carrying a step consistent with its public clock.

    The frozen base module reads ``obs['step']`` directly, so a seat-one
    observation without the key must not reach it unchanged.  An observation
    that already carries the right step is returned as-is.
    """
    step = _step_of(obs)
    current = _get(obs, "step", None)
    if current is not None:
        try:
            if int(current) == step:
                return obs
        except (TypeError, ValueError):
            pass
    if isinstance(obs, dict):
        normalized = dict(obs)
        normalized["step"] = step
        return normalized
    try:
        obs.step = step
    except (AttributeError, TypeError):
        pass
    return obs


def _seat(obs):
    return 1 if int(_get(obs, "player", 0) or 0) == 1 else 0


def _farm(obs, seat):
    farms = list(_get(obs, "farms", []) or [])
    return farms[seat] if seat < len(farms) else {}


def _private(obs):
    return _get(obs, "private", {}) or {}


def _market_prices(obs):
    return dict(_get(_get(obs, "market", {}) or {}, "prices", {}) or {})


def _copy_action(action):
    raw = copy.deepcopy(action or {})
    return {
        "farmer": list(raw.get("farmer") or ["PASS"]),
        "hands": [list(order or ["PASS"]) for order in (raw.get("hands") or [])],
        "market": [list(order) for order in (raw.get("market") or [])],
    }


def _reset_if_needed(seat, step):
    state = _STATE[seat]
    if step == 0 or step < int(state.get("last_step", -1)):
        state.update(
            last_step=step,
            wheat_credit=0,
            salvage_active=False,
            salvage_actor=-1,
            salvage_target=(0, 0),
            salvage_product=None,
            salvage_quantity=0,
        )
    else:
        state["last_step"] = step
    return state


def _base_sheep_pressure(seat):
    try:
        return bool(_BASE.__dict__["_STATE"][seat].get("sheep_pressure", False))
    except Exception:
        return False


def _observe_embedded_moon(obs, step, clone_distance):
    # Embedded FC16 learns horizons only while the public boards remain close.
    # The source observer must still run outside that regime so its previous
    # inventory/price/shop snapshot and 0.999 decay remain sequential.
    original = int(_MOON.__dict__.get("_PREEMPT_MIN_FUTURE_QUANTITY", 4))
    _MOON.__dict__["_ADAPT_MIN_EVIDENCE"] = 1.5
    if clone_distance > 6:
        _MOON.__dict__["_PREEMPT_MIN_FUTURE_QUANTITY"] = 10**9
    try:
        _MOON.__dict__["_observe_opponent_market"](obs, step)
    finally:
        _MOON.__dict__["_PREEMPT_MIN_FUTURE_QUANTITY"] = original


def _moon_h4_overlay(obs, action, step, seat):
    clone_distance = int(_MOON.__dict__["_clone_distance"](obs))
    _observe_embedded_moon(obs, step, clone_distance)
    action = _MOON.__dict__["_repay_shift"](obs, _copy_action(action), step)
    race = _MOON.__dict__["_race_state"](obs, step)
    if step >= 120 and clone_distance <= 2:
        horizons = race.setdefault("horizon", {})
        for product in _MOON.__dict__["_PREMIUM"]:
            horizons[product] = max(4, int(horizons.get(product, 1) or 1))
    if not _base_sheep_pressure(seat) and clone_distance <= 6:
        action = _MOON.__dict__["_preempt_shift"](obs, action, step)
    _MOON.__dict__["_record_own_sells"](obs, action, step)
    return action


def _opening_and_cash_guards(action, step):
    market = [list(order) for order in (action.get("market") or [])]
    for order in market:
        if len(order) < 3:
            continue
        if step == 0 and order[0] == "BUY_SEED" and order[1] == "WHEAT":
            order[2] = 8
        if (
            72 < step < 192
            and order[0] == "BUY_SEED"
            and order[1] == "CARROT"
            and int(order[2] or 0) >= 5
        ):
            order[2] = max(0, int(order[2] or 0) - 1)
    action["market"] = market[:10]
    return action


def _unit_positions(farm):
    return [
        list(_get(farm, "farmer", [0, 0]) or [0, 0]),
        *[list(value or [0, 0]) for value in (_get(farm, "hands", []) or [])],
    ]


def _unit_orders(action):
    return [action.get("farmer", ["PASS"]), *list(action.get("hands") or [])]


def _set_unit_order(action, actor, order):
    if actor == 0:
        action["farmer"] = list(order)
    elif 0 < actor <= len(action.get("hands") or []):
        action["hands"][actor - 1] = list(order)


def _tile_at(farm, position):
    try:
        x, y = int(position[0]), int(position[1])
        return (_get(farm, "tiles", []) or [])[y][x]
    except (IndexError, TypeError, ValueError):
        return None


def _feed_value_guard(obs, action, step, seat, state):
    farm = _farm(obs, seat)
    prices = _market_prices(obs)
    positions = _unit_positions(farm)
    orders = _unit_orders(action)
    skipped = 0
    if step // 24 >= 10:
        for actor, order in enumerate(orders):
            if not isinstance(order, (list, tuple)) or not order or order[0] != "FEED":
                continue
            if actor >= len(positions):
                continue
            tile = _tile_at(farm, positions[actor])
            if not isinstance(tile, dict):
                continue
            animal = str(tile.get("animal") or "")
            product = _ANIMAL_PRODUCT.get(animal)
            if product is None:
                continue
            if bool(tile.get("fed_today", False)):
                continue
            if int(tile.get("consecutive_unfed", 0) or 0) != 0:
                continue
            pending = max(0, int(tile.get("pending_care_bonus", 0) or 0))
            product_value = int(prices.get(product, 0) or 0) * (1 + pending)
            wheat_price = int(prices.get("WHEAT", 0) or 0)
            if product_value < wheat_price:
                _set_unit_order(action, actor, ["PASS"])
                skipped += 1
    credit = max(0, int(state.get("wheat_credit", 0) or 0)) + skipped
    market = []
    for raw in action.get("market", []) or []:
        order = list(raw)
        if (
            credit > 0
            and len(order) >= 3
            and order[0] == "BUY_PRODUCT"
            and order[1] == "WHEAT"
        ):
            requested = max(0, int(order[2] or 0))
            take = min(requested, credit)
            requested -= take
            credit -= take
            if requested <= 0:
                continue
            order[2] = requested
        market.append(order)
    action["market"] = market[:10]
    state["wheat_credit"] = credit
    return action


def _nearest_evac(position):
    x, y = int(position[0]), int(position[1])
    distance = [abs(x - tx) + abs(y - ty) for tx, ty in _EVAC_ACCESS]
    index = min(range(len(distance)), key=lambda i: distance[i])
    return _EVAC_ACCESS[index], distance[index]


def _move_toward(position, target):
    x, y = int(position[0]), int(position[1])
    tx, ty = int(target[0]), int(target[1])
    if x < tx:
        return ["EAST"]
    if x > tx:
        return ["WEST"]
    if y < ty:
        return ["SOUTH"]
    if y > ty:
        return ["NORTH"]
    return ["PASS"]


def _planned_sales(action):
    out = {product: 0 for product in _PRODUCTS}
    for order in action.get("market", []) or []:
        if (
            isinstance(order, (list, tuple))
            and len(order) >= 3
            and order[0] == "SELL"
            and order[1] in out
        ):
            out[order[1]] += max(0, int(order[2] or 0))
    return out


def _append_or_merge_sale(action, product, quantity):
    market = [list(order) for order in (action.get("market") or [])]
    for order in market:
        if len(order) >= 3 and order[0] == "SELL" and order[1] == product:
            order[2] = int(order[2] or 0) + int(quantity)
            action["market"] = market[:10]
            return action
    if len(market) < 10:
        market.append(["SELL", product, int(quantity)])
    action["market"] = market[:10]
    return action


def _terminal_crop_salvage(obs, action, step, seat, state):
    farm = _farm(obs, seat)
    private = _private(obs)
    positions = _unit_positions(farm)
    orders = _unit_orders(action)
    inventories = list(_get(private, "inventories", []) or [])
    prices = _market_prices(obs)
    day = step // 24

    selected = None
    if not state.get("salvage_active", False) and step >= 696:
        for actor, (position, order) in enumerate(zip(positions, orders)):
            if not isinstance(order, (list, tuple)) or not order or order[0] not in _MOVE_OPS:
                continue
            tile = _tile_at(farm, position)
            if not isinstance(tile, dict):
                continue
            crop = str(tile.get("crop") or "")
            if crop not in _CROP_FIRST_YIELD_DAY:
                continue
            tile_yield = int(tile.get("yield_units", 0) or 0)
            planted_day = int(tile.get("planted_day", -1) or 0)
            if tile_yield <= 0 or day - planted_day < _CROP_FIRST_YIELD_DAY[crop]:
                continue
            target, distance = _nearest_evac(position)
            if distance + 2 != 719 - step:
                continue
            inventory = dict(inventories[actor] or {}) if actor < len(inventories) else {}
            carried_value = sum(
                max(0, int(inventory.get(product, 0) or 0))
                * int(prices.get(product, 0) or 0)
                for product in _PRODUCTS
            )
            crop_value = tile_yield * int(prices.get(crop, 0) or 0)
            if crop_value < 2 * carried_value:
                continue
            score = crop_value * 100 - actor
            if selected is None or score > selected[0]:
                selected = (score, actor, target, crop, tile_yield)

    if selected is not None:
        _, actor, target, product, quantity = selected
        state.update(
            salvage_active=True,
            salvage_actor=actor,
            salvage_target=tuple(target),
            salvage_product=product,
            salvage_quantity=quantity,
        )
        _set_unit_order(action, actor, ["HARVEST"])
    elif state.get("salvage_active", False):
        actor = int(state.get("salvage_actor", -1))
        target = tuple(state.get("salvage_target", (0, 0)))
        if 0 <= actor < len(positions):
            if tuple(positions[actor]) == target:
                _set_unit_order(action, actor, ["DROP"])
            else:
                _set_unit_order(action, actor, _move_toward(positions[actor], target))

    actor = int(state.get("salvage_actor", -1))
    drop = (
        state.get("salvage_active", False)
        and 0 <= actor < len(positions)
        and tuple(positions[actor]) == tuple(state.get("salvage_target", (0, 0)))
        and step == 718
    )
    if drop:
        projected = _MOON.__dict__["_projected_shed"](obs, action)
        planned = _planned_sales(action)
        product = state.get("salvage_product")
        quantity = max(0, int(state.get("salvage_quantity", 0) or 0))
        incremental = min(
            quantity,
            max(0, int(projected.get(product, 0) or 0) - planned.get(product, 0)),
        )
        if incremental > 0:
            action = _append_or_merge_sale(action, product, incremental)
    return action


def agent(obs, configuration=None):
    obs = _step_normalized(obs)
    step = min(max(0, _step_of(obs)), 718)
    seat = _seat(obs)
    state = _reset_if_needed(seat, step)
    action = _copy_action(_BASE.__dict__["agent"](obs, configuration))
    action = _moon_h4_overlay(obs, action, step, seat)
    action = _opening_and_cash_guards(action, step)
    action = _feed_value_guard(obs, action, step, seat, state)
    action = _terminal_crop_salvage(obs, action, step, seat, state)
    return action


__version__ = "FC24B-fc22-plus-value-guarded-terminal-crop-salvage-cpu-v1"
